import { getUser, oauthLogin, logout, handleAuthCallback } from '@netlify/identity';
import COURSE from './curriculum.json';
import { CAPSTONES } from './lib/chapter-capstone.mjs';
import { buildPortfolioExport, buildCoordinatorSummary } from './lib/portfolio-export.mjs';

const PROGRAMME_NAME='AI in Practice — Transition Year pilot';
const ANON_KEY='ty-ai-anon-progress';
const emptyState=()=>({completed:[],reflections:{},activity:{},badges:[],chapterAssessments:{}});
let user=null;
let state=emptyState();
let activeBlock=null;
let activeSession=null;
let syncTimer=null;
// Set when Google sign-in succeeded but the progress API is unreachable/misconfigured.
// While set, work is kept on this device only and never pushed to the cloud, so a
// stale local copy cannot overwrite the learner's cloud progress when the API recovers.
let cloudError=null;

const esc=(v='')=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot',"'":'&#39;'}[c]));
function sanitizeState(v){
  const s=emptyState();
  if(!v||typeof v!=='object')return s;
  s.completed=Array.isArray(v.completed)?[...new Set(v.completed.filter(x=>typeof x==='string'))]:[];
  s.reflections=v.reflections&&typeof v.reflections==='object'?v.reflections:{};
  s.activity=v.activity&&typeof v.activity==='object'?v.activity:{};
  s.badges=Array.isArray(v.badges)?[...new Set(v.badges.filter(x=>typeof x==='string'))]:[];
  s.chapterAssessments=v.chapterAssessments&&typeof v.chapterAssessments==='object'?v.chapterAssessments:{};
  return s;
}
function localKey(){return user?.id&&!cloudError?`ty-ai-progress:${user.id}`:ANON_KEY}
function loadLocal(key=localKey()){try{return sanitizeState(JSON.parse(localStorage.getItem(key)||'{}'))}catch{return emptyState()}}
function saveLocal(){localStorage.setItem(localKey(),JSON.stringify(state))}
function isEmpty(s){return !s.completed.length&&!Object.keys(s.reflections).length&&!Object.keys(s.activity).length&&!Object.keys(s.chapterAssessments).length}

async function api(path,opts={}){const r=await fetch('/api/'+path,{credentials:'same-origin',headers:{'content-type':'application/json',...(opts.headers||{})},...opts});let d={};try{d=await r.json()}catch{}if(!r.ok){const e=new Error(d.error||`Request failed (HTTP ${r.status})`);e.status=r.status;throw e}return d}
function setSync(text,kind=''){const el=document.getElementById('syncStatus');if(!el)return;el.textContent=text;el.className='sync '+kind}
function allSessions(){return COURSE.blocks.flatMap(b=>b.sessions)}
function blockDone(b){return b.sessions.every(s=>state.completed.includes(s.id))}
function blockQualified(b){return Boolean(state.chapterAssessments?.[b.id]?.submittedAt)}
function blockUnlocked(i){return i===0||(blockDone(COURSE.blocks[i-1])&&blockQualified(COURSE.blocks[i-1]))}
function reconcileBadges(){state.badges=COURSE.blocks.filter(b=>blockQualified(b)).map(b=>b.badge)}
function pct(){return Math.round(state.completed.length/allSessions().length*100)}
function renderProgress(){const p=pct();document.getElementById('coursePct').textContent=p+'%';document.getElementById('courseBar').style.width=p+'%'}
function show(id){['homeView','blockView','portfolioView'].forEach(x=>document.getElementById(x).classList.toggle('hidden',x!==id))}

async function scheduleSync(){saveLocal();renderProgress();if(!user||cloudError)return;clearTimeout(syncTimer);setSync('Saving…');syncTimer=setTimeout(async()=>{try{await api('progress',{method:'PUT',body:JSON.stringify({state})});setSync('Cloud synced','online')}catch{setSync('Saved on this device','error')}},400)}

function renderHome(){
  reconcileBadges();
  renderProgress();
  const signed=Boolean(user);
  document.getElementById('welcomeName').textContent=signed?`Welcome, ${user.displayName}`:'';
  document.getElementById('authBtn').innerHTML=signed?'Sign out':'<span class="gmark">G</span><span>Continue with Google</span>';
  document.getElementById('authBtn').classList.toggle('google-btn',!signed);
  document.getElementById('accountTitle').textContent=!signed?'Sign in to save across devices':cloudError?'Signed in · cloud sync unavailable':`Progress saved for ${user.displayName}`;
  document.getElementById('accountText').textContent=!signed?'Use a Google account to continue your course from another browser or device.':cloudError?`Signed in with ${user.email}, but the progress service could not be reached (${cloudError}). Your work is being saved on this device only. Reload the page to try again.`:`Signed in with ${user.email}. Your evidence and progress are stored against your account.`;
  document.getElementById('accountAction').innerHTML=signed?'Sign out':'<span class="gmark">G</span><span>Continue with Google</span>';
  document.getElementById('chaptersHeading').textContent=`Chapters 1–${COURSE.blocks.length}`;
  document.getElementById('blockGrid').innerHTML=COURSE.blocks.map((b,i)=>{
    const unlocked=blockUnlocked(i),sessionsDone=blockDone(b),qualified=blockQualified(b),done=sessionsDone&&qualified,last=i===COURSE.blocks.length-1;
    let status='Start / Continue';
    if(done)status=last?`Badge earned: ${b.badge} ✓ · Programme complete`:'✓ Complete';
    else if(sessionsDone)status='Chapter assessment required';
    else if(!unlocked)status=`🔒 Complete Chapter ${COURSE.blocks[i-1].number} assessment`;
    return `<button class="block-card block-${i+1} ${done?'done':''} ${done&&last?'programme-complete':''} ${!unlocked?'locked':''}" data-block="${i}" ${unlocked?'':'disabled'}><div class="card-top"><span>CHAPTER ${b.number}</span><span>${esc(b.duration)}</span></div><h2>${esc(b.title)}</h2><p>${esc(b.description)}</p><div class="card-bottom"><span class="badge-pill">${esc(b.badge)}</span><strong>${esc(status)}</strong></div></button>`;
  }).join('');
  document.querySelectorAll('[data-block]').forEach(x=>x.onclick=()=>openBlock(Number(x.dataset.block)));
}

function openBlock(i){if(!blockUnlocked(i))return;activeBlock=COURSE.blocks[i];activeSession=activeBlock.sessions.find(s=>!state.completed.includes(s.id))||activeBlock.sessions[0];document.getElementById('blockMeta').textContent=`CHAPTER ${activeBlock.number} · ${activeBlock.duration}`;document.getElementById('blockTitle').textContent=activeBlock.title;document.getElementById('blockDesc').textContent=activeBlock.description;document.getElementById('blockBadge').textContent=activeBlock.badge;document.getElementById('blockLO').innerHTML=activeBlock.outcomes.map(x=>`<span class="tag">${esc(x)}</span>`).join('');document.getElementById('blockMission').textContent=activeBlock.mission;document.getElementById('blockRoute').innerHTML=activeBlock.route.map(r=>`<div><strong>${esc(r[0])}</strong><span>${esc(r[1])}</span></div>`).join('');renderRubric();renderLabBanner();renderMyths();renderSessionNav();renderLesson();show('blockView')}
function renderMyths(){const el=document.getElementById('mythBusters'),myths=activeBlock?.myths;if(!el)return;if(!Array.isArray(myths)||!myths.length){el.innerHTML='';return}el.innerHTML=`<div class="eyebrow">MYTH-BUSTERS</div><div class="myth-grid"><b>People say</b><b>Actually</b>${myths.map(([say,actually])=>`<p class="myth-say">“${esc(say)}”</p><p class="myth-actually">${esc(actually)}</p>`).join('')}</div>`}
// Chapter 8 judging criteria (Student Book p.41: “Read them before you start, not after.”). Only a block that sets
// `rubric` renders a table; every earlier chapter leaves the container empty. Rows are [criterion, started, there, further].
function rubricHTML(b){const r=b?.rubric,rows=Array.isArray(r)?r.map(x=>[x[0],x.slice(1)]):r&&typeof r==='object'?Object.entries(r).map(([k,v])=>[k,Array.isArray(v)?v:[]]):[];if(!rows.length)return '';return `<div class="eyebrow">HOW YOUR PROJECT WILL BE JUDGED</div><p class="muted">Six criteria. Read them before you start, not after.</p><div class="table-wrap"><table class="rubric-table"><thead><tr><th>Criterion</th><th>Getting started</th><th>Getting there</th><th>Going further</th></tr></thead><tbody>${rows.map(([name,levels])=>`<tr data-criterion="${esc(name)}"><th>${esc(name)}</th>${[0,1,2].map(i=>`<td>${esc(levels[i]||'')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function renderRubric(){const el=document.getElementById('chapterRubric');if(!el)return;el.innerHTML=rubricHTML(activeBlock)}
function selfCheckHTML(b){const sc=b?.selfCheck;if(!sc||typeof sc!=='object'||!Object.keys(sc).length)return '';return `<div class="self-check"><strong>How am I doing?</strong><p class="muted">Before you submit, which of these can you honestly say?</p><div class="self-check-grid">${Object.entries(sc).map(([level,items])=>`<div><b>${esc(level)}</b><ul>${(Array.isArray(items)?items:[]).map(i=>`<li>${esc(i)}</li>`).join('')}</ul></div>`).join('')}</div></div>`}
function levelUpHTML(b){return b?.levelUp?`<p class="level-up"><b>Level up · optional challenge</b> ${esc(b.levelUp)}</p>`:''}
function renderLabBanner(){const el=document.getElementById('labBanner'),lab=activeBlock?.lab;if(!el)return;if(!lab){el.innerHTML='';return}el.innerHTML=`<div class="eyebrow">EXPERIENCE LAB</div><h3>${esc(lab.title)}</h3><p>${esc(lab.summary)}</p><div class="lab-stages">${lab.stages.map(([tag,sid,label])=>`<button type="button" class="lab-stage ${state.completed.includes(sid)?'done':''}" data-lab-session="${esc(sid)}"><b>${esc(tag)}</b><span>${esc(label)}</span></button>`).join('')}</div>`;el.querySelectorAll('[data-lab-session]').forEach(x=>x.onclick=()=>{activeSession=activeBlock.sessions.find(s=>s.id===x.dataset.labSession)||activeSession;renderSessionNav();renderLesson()})}
function renderSessionNav(){renderLabBanner();document.getElementById('sessionNav').innerHTML=activeBlock.sessions.map((s,i)=>`<button class="session-link ${s.id===activeSession.id?'active':''} ${state.completed.includes(s.id)?'done':''}" data-session="${s.id}"><span>${i+1}</span><div>${esc(s.title)}<small>${s.minutes} min</small></div>${state.completed.includes(s.id)?'<b>✓</b>':''}</button>`).join('');document.querySelectorAll('[data-session]').forEach(x=>x.onclick=()=>{activeSession=activeBlock.sessions.find(s=>s.id===x.dataset.session);renderSessionNav();renderLesson()})}

function studyHTML(s){return `<section class="studybox"><div class="study-head"><div><div class="eyebrow">DISCOVER · STUDY FIRST</div><h3>${esc(s.study.title)}</h3></div><span>${esc(s.pageRef)}</span></div>${s.study.body.map(p=>`<p>${esc(p)}</p>`).join('')}<div class="example"><strong>Example</strong><p>${esc(s.study.example)}</p></div><div class="keywords">${s.study.keywords.map(k=>`<span>${esc(k)}</span>`).join('')}</div></section>`}

function downloadsHTML(a){if(!Array.isArray(a.downloads)||!a.downloads.length)return '';return `<div class="downloads"><strong>Downloads for this session</strong><ul>${a.downloads.map(d=>`<li><a href="/datasets/${esc(d.file)}" download>${esc(d.label)}</a><span>${esc(d.note||'')}</span></li>`).join('')}</ul></div>`}
function safetyHTML(a,v){if(!Array.isArray(a.privacy)||!a.privacy.length||!a.tool)return '';const ack=Boolean(v.ack);return `<div class="lab-privacy"><strong>Before you open ${esc(a.tool.name)}</strong><ul>${a.privacy.map(p=>`<li>${esc(p)}</li>`).join('')}</ul><label class="lab-ack"><input type="checkbox" data-ack ${ack?'checked':''}> I have read this and will follow it</label></div><div class="lab-tools"><a id="labToolLink" class="primary external ${ack?'':'disabled'}" href="${esc(a.tool.url)}" target="_blank" rel="noopener" aria-disabled="${ack?'false':'true'}">Open ${esc(a.tool.name)} ↗</a></div>`}
function activityHTML(s){return activityBodyHTML(s)+downloadsHTML(s.activity)}
// Dataset activity (Chapter 3 Data Detective). Parsed CSVs are cached per file so re-renders never refetch.
const DATASETS=new Map();
function parseCSV(text){const t=String(text).replace(/^\uFEFF/,'');const rows=[];let row=[],field='',q=false;for(let i=0;i<t.length;i++){const c=t[i];if(q){if(c==='"'){if(t[i+1]==='"'){field+='"';i++}else q=false}else field+=c}else if(c==='"')q=true;else if(c===','){row.push(field);field=''}else if(c==='\n'||c==='\r'){if(c==='\r'&&t[i+1]==='\n')i++;row.push(field);rows.push(row);row=[];field=''}else field+=c}if(field.length||row.length){row.push(field);rows.push(row)}const [columns=[],...body]=rows;return {columns,rows:body.filter(r=>!(r.length===1&&r[0]===''))}}
function loadDataset(file){if(!DATASETS.has(file))DATASETS.set(file,fetch(`/datasets/${file}`).then(r=>{if(!r.ok)throw new Error(`Dataset not available (HTTP ${r.status})`);return r.text()}).then(parseCSV).catch(err=>{DATASETS.delete(file);throw err}));return DATASETS.get(file)}
function datasetSummary(d){return d.columns.map((name,i)=>{const vals=d.rows.map(r=>String(r[i]??'').trim()).filter(Boolean);const counts=new Map();for(const v of vals)counts.set(v,(counts.get(v)||0)+1);const top=[...counts.entries()].sort((a,b)=>b[1]-a[1]).slice(0,3);return {name,filled:vals.length,distinct:counts.size,sample:vals[0]||'—',top}})}
function datasetHTML(s,d,readOnly=false){const a=s.activity,rows=d.rows;return `<div class="dataset-summary">${datasetSummary(d).map(c=>`<button type="button" class="dataset-col" data-target="column:${esc(c.name)}"><b>${esc(c.name)}</b><span>${c.filled}/${d.rows.length} filled · ${c.distinct} distinct</span><em>${c.top.map(([v,n])=>`${esc(String(v).slice(0,14))} ×${n}`).join(' · ')||'—'}</em></button>`).join('')}</div><div class="dataset-wrap"><table class="dataset-table"><thead><tr><th>#</th>${d.columns.map(c=>`<th><button type="button" data-target="column:${esc(c)}">${esc(c)}</button></th>`).join('')}</tr></thead><tbody>${rows.map((r,i)=>`<tr><th><button type="button" data-target="row:${i+1}">${i+1}</button></th>${d.columns.map((_,j)=>`<td>${esc(r[j]??'')}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="muted">All ${d.rows.length} rows · ${d.columns.length} columns.${readOnly?'':' Click a column name or row number to target it in a finding.'}</p>${readOnly?'':`<form class="finding-form" data-finding-form><label><span>Target</span><select id="datasetTarget" name="target"><option value="table">Whole table</option>${d.columns.map(c=>`<option value="column:${esc(c)}">Column: ${esc(c)}</option>`).join('')}${d.rows.map((_,i)=>`<option value="row:${i+1}">Row ${i+1}</option>`).join('')}</select></label><label><span>Issue</span><select id="datasetIssue" name="issue">${a.issueTypes.map(t=>`<option>${esc(t)}</option>`).join('')}</select></label><label><span>Note</span><input id="datasetNote" name="note" placeholder="What is wrong and why it matters…"></label><button id="datasetAdd" type="submit" class="secondary">Add finding</button></form><div class="findings dataset-findings"><strong>Your findings</strong><ol id="findingsList"></ol></div>`}`}
function findingsListHTML(s){const a=s.activity,f=(state.activity[s.id]||{}).findings||[];return f.length?f.map((x,i)=>`<li><b>${esc(x.issue)}</b> at <code>${esc(x.target)}</code>: ${esc(x.note)} <button type="button" class="finding-remove" data-remove="${i}" aria-label="Remove finding ${i+1}: ${esc(x.issue)} at ${esc(x.target)}">Remove</button></li>`).join(''):`<li class="muted">No findings yet. Record at least ${a.minFindings||5} findings across 3 different issue types${Array.isArray(a.requiredIssues)&&a.requiredIssues.length?`, including at least one "${esc(a.requiredIssues.join('" and one "'))}" finding`:''}.</li>`}
function wireDataset(s,host){const readOnly=host.hasAttribute('data-readonly');loadDataset(s.activity.file).then(d=>{if(!host.isConnected)return;host.innerHTML=datasetHTML(s,d,readOnly);if(readOnly)return;const form=host.querySelector('[data-finding-form]'),list=host.querySelector('#findingsList'),tgt=form.querySelector('[name=target]'),iss=form.querySelector('[name=issue]'),note=form.querySelector('[name=note]');const paint=()=>{list.innerHTML=findingsListHTML(s);list.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{const idx=Number(b.dataset.remove);const cur=state.activity[s.id]||{};state.activity[s.id]={...cur,findings:(cur.findings||[]).filter((_,i)=>i!==idx)};scheduleSync();paint();const btns=list.querySelectorAll('[data-remove]');(btns[Math.min(idx,btns.length-1)]||note).focus()})};paint();host.querySelectorAll('[data-target]').forEach(b=>b.onclick=()=>{tgt.value=b.dataset.target;note.focus()});note.oninput=()=>note.setCustomValidity('');form.onsubmit=e=>{e.preventDefault();const text=note.value.trim();if(text.length<12){note.setCustomValidity('Write at least 12 characters explaining what you found and why it matters.');note.reportValidity();return}const cur=state.activity[s.id]||{};state.activity[s.id]={...cur,findings:[...(cur.findings||[]),{target:tgt.value,issue:iss.value,note:text}]};note.value='';feedback('activityFeedback','');scheduleSync();paint()}}).catch(err=>{if(host.isConnected)host.innerHTML=`<p class="result warn">${esc(err.message)}. Download the file below and open it in a spreadsheet instead.</p>`})}
// Prompt Lab (Chapter 4, Sheet A4). The four C-T-C-F hints are the Student Book p.20 boxes, verbatim.
const PROMPT_BUILDER=[['context','Context','Who you are, what this is for, what you already know'],['task','Task','The one clear thing you want it to do. One verb.'],['constraints','Constraints','Length, level, what to avoid, what must be included'],['format','Format','Table? Bullets? Three options? Questions first?']];
// AI News Detective (Chapter 5, the book's highlighter pass). The article is a plain-text download split into sentences on the sentence-ending full stop; the content contract keeps the file free of mid-sentence full stops so the numbering is stable.
const TEXTS=new Map();
function loadText(file){if(!TEXTS.has(file))TEXTS.set(file,fetch(`/datasets/${file}`).then(r=>{if(!r.ok)throw new Error(`Article not available (HTTP ${r.status})`);return r.text()}).catch(err=>{TEXTS.delete(file);throw err}));return TEXTS.get(file)}
function splitSentences(text){return String(String(text).trim().split(/\n\s*\n/).pop()).replace(/\s+/g,' ').trim().split(/(?<=[.!?])\s+/).map(x=>x.trim()).filter(Boolean)}
function annotateMarks(s){const m=(state.activity[s.id]||{}).marks;return Array.isArray(m)?m:[]}
function annotateArticleHTML(s,sentences){const marks=annotateMarks(s);return sentences.map((t,i)=>{const n=i+1,types=[...new Set(marks.filter(m=>m.sentence===n).map(m=>m.type))];return `<button type="button" class="annotate-sentence ${types.length?'marked':''}" data-sentence="${n}" aria-label="Sentence ${n}${types.length?`, marked ${esc(types.join(', '))}`:''}">${esc(t)}${types.length?`<small class="annotate-tag">${esc(types.join(' · '))}</small>`:''}</button> `}).join('')}
function annotateFindingsHTML(s){const a=s.activity,marks=annotateMarks(s);return marks.length?marks.map((m,i)=>`<li><b>${esc(m.type)}</b> at sentence ${Number(m.sentence)||0}: ${esc(m.note)} <button type="button" class="finding-remove" data-remove="${i}" aria-label="Remove mark ${i+1}: ${esc(m.type)} at sentence ${Number(m.sentence)||0}">Remove</button></li>`).join(''):`<li class="muted">No marks yet. Mark at least ${a.minMarks||6} sentences across 3 different mark types${Array.isArray(a.requiredMarks)&&a.requiredMarks.length?`, including at least one "${esc(a.requiredMarks.join('" and one "'))}"`:''}. Count them.</li>`}
function annotateCountsHTML(s){const marks=annotateMarks(s);return (s.activity.markTypes||[]).map(t=>`<span><b>${esc(t)}</b> ×${marks.filter(m=>m.type===t).length}</span>`).join('')}
function wireAnnotate(s,host){const a=s.activity;loadText(a.file).then(text=>{if(!host.isConnected)return;const sentences=splitSentences(text);let sel=0;host.innerHTML=`<div class="annotate-article" data-annotate-article></div><form class="annotate-form" data-annotate-form><p id="annotateTarget" class="annotate-target">Click a sentence in the article to select it.</p><label><span>Mark as</span><select id="annotateMark" name="mark">${(a.markTypes||[]).map(t=>`<option>${esc(t)}</option>`).join('')}</select></label><label class="annotate-note"><span>Note</span><textarea id="annotateNote" name="note" rows="2" placeholder="What is claimed, what is missing, or what the wording makes you feel…"></textarea></label><button id="annotateAdd" type="submit" class="secondary">Add mark</button></form><div class="annotate-counts" aria-live="polite"></div><div class="findings annotate-findings"><strong>Your marks</strong><ol></ol></div>`;const art=host.querySelector('[data-annotate-article]'),form=host.querySelector('[data-annotate-form]'),target=host.querySelector('#annotateTarget'),mark=host.querySelector('#annotateMark'),note=host.querySelector('#annotateNote'),counts=host.querySelector('.annotate-counts'),list=host.querySelector('.annotate-findings ol');const paint=()=>{art.innerHTML=annotateArticleHTML(s,sentences);art.querySelectorAll('[data-sentence]').forEach(b=>{b.classList.toggle('selected',Number(b.dataset.sentence)===sel);b.onclick=()=>{sel=Number(b.dataset.sentence);art.querySelectorAll('[data-sentence]').forEach(x=>x.classList.toggle('selected',x===b));target.textContent=`Sentence ${sel}: ${sentences[sel-1]}`;note.focus()}});counts.innerHTML=annotateCountsHTML(s);list.innerHTML=annotateFindingsHTML(s);list.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{const idx=Number(b.dataset.remove);const cur=state.activity[s.id]||{};state.activity[s.id]={...cur,marks:annotateMarks(s).filter((_,i)=>i!==idx)};scheduleSync();paint();const btns=list.querySelectorAll('[data-remove]');(btns[Math.min(idx,btns.length-1)]||note).focus()})};paint();note.oninput=()=>note.setCustomValidity('');form.onsubmit=e=>{e.preventDefault();if(!sel){feedback('activityFeedback','Click a sentence in the article first.','warn');return}const text=note.value.trim();if(text.length<8){note.setCustomValidity('Write at least 8 characters saying why this sentence gets this mark.');note.reportValidity();return}const cur=state.activity[s.id]||{};state.activity[s.id]={...cur,marks:[...annotateMarks(s),{sentence:sel,type:mark.value,note:text}]};note.value='';feedback('activityFeedback','');scheduleSync();paint()}}).catch(err=>{if(host.isConnected)host.innerHTML=`<p class="result warn">${esc(err.message)}. Download the article below and mark it up on paper or in your notes instead.</p>`})}
// Bias simulator (Chapter 5, review §8.1 subgroup table and §8.2 proxy point). Deterministic: Group A always 18/20; Group B climbs with representation; the sensitive field costs Group B six correct decisions, and removing it helps only as much as the proxy is weak.
function simModel(shareB,proxy,removed){const correctA=18,penalty=Math.round(6*(removed?proxy/100:1)),correctB=Math.max(0,Math.min(20,Math.round(6+12*shareB/50)-penalty));return {correctA,correctB,overall:(correctA+correctB)/40}}
const simPct=x=>String(Math.round(x*1000)/10);
function simRunsHTML(s){const runs=(state.activity[s.id]||{}).runs;return Array.isArray(runs)&&runs.length?runs.map((r,i)=>`<li>Run ${i+1}: Group B ${Number(r.shareB)||0}% of training data · proxy ${Number(r.proxy)||0}% · sensitive field ${r.removed?'removed':'kept'} → Group A ${Number(r.correctA)||0}/20 (${simPct(r.correctA/20)}%), Group B ${Number(r.correctB)||0}/20 (${simPct(r.correctB/20)}%), overall ${(Number(r.correctA)||0)+(Number(r.correctB)||0)}/40 (${simPct(r.overall)}%)</li>`).join(''):`<li class="muted">No runs recorded yet. Record at least ${s.activity.minRuns||2} runs with different settings.</li>`}
function activityBodyHTML(s){const a=s.activity,v=state.activity[s.id]||{};if(a.kind==='quiz')return `<div class="quiz-list">${a.items.map((it,i)=>`<label><span>${esc(it[0])}</span><select data-i="${i}"><option value="">Choose…</option>${a.options.map(o=>`<option value="${esc(o)}" ${v[i]===o?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`).join('')}</div>`;
if(a.kind==='daymap')return `<div class="daymap"><div class="daymap-head">Service · Input · AI action · Output · Benefit · Risk</div>${Array.from({length:a.rows},(_,i)=>{const r=v[i]||{};return `<div class="dayrow"><input data-i="${i}" data-f="service" placeholder="Service" value="${esc(r.service||'')}"><input data-i="${i}" data-f="input" placeholder="Input" value="${esc(r.input||'')}"><input data-i="${i}" data-f="action" placeholder="AI action" value="${esc(r.action||'')}"><input data-i="${i}" data-f="output" placeholder="Output" value="${esc(r.output||'')}"><input data-i="${i}" data-f="benefit" placeholder="Benefit" value="${esc(r.benefit||'')}"><input data-i="${i}" data-f="risk" placeholder="Risk" value="${esc(r.risk||'')}"></div>`}).join('')}</div>`;
if(a.kind==='chain'){const cols=a.columns||[];return `<div class="chain" style="--chain-cols:${cols.length}">${safetyHTML(a,v)}<div class="daymap-head">${esc(a.head||cols.map(c=>c[1]).join(' → '))}</div>${Array.from({length:a.rows},(_,i)=>{const r=v[i]||{};return `<div class="chainrow">${cols.map(([k,l])=>`<input data-i="${i}" data-f="${esc(k)}" placeholder="${esc(l)}" aria-label="Row ${i+1} ${esc(l)}" value="${esc(r[k]||'')}">`).join('')}</div>`}).join('')}</div>`}
if(a.kind==='textfields')return `${safetyHTML(a,v)}<div class="text-fields">${a.fields.map((f,i)=>`<label><span>${esc(f)}</span><textarea data-i="${i}" placeholder="Write in your own words…">${esc(v[i]||'')}</textarea></label>`).join('')}</div>`;
if(a.kind==='external')return `<ol class="steps">${a.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><a class="primary external" href="${a.url}" target="_blank" rel="noopener">Open model tool ↗</a><label class="record"><span>Your experiment record</span><textarea data-single placeholder="Classes, example counts, conditions and what happened…">${esc(v.text||'')}</textarea></label>`;
if(a.kind==='dataset')return `<div class="dataset" data-dataset="${esc(a.file)}"><p class="muted">Loading ${esc(a.file)}…</p></div>`;
if(a.kind==='lab'){const ack=Boolean(v.ack),fb=v.mode==='fallback';return `<div class="lab"><div class="lab-privacy"><strong>Before you open ${esc(a.tool.name)}</strong><ul>${a.privacy.map(p=>`<li>${esc(p)}</li>`).join('')}</ul><label class="lab-ack"><input type="checkbox" data-ack ${ack?'checked':''}> I have read this and will follow it</label></div><ol class="steps">${a.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><div class="lab-tools"><a id="labToolLink" class="primary external ${ack?'':'disabled'}" href="${esc(a.tool.url)}" target="_blank" rel="noopener" aria-disabled="${ack?'false':'true'}">Open ${esc(a.tool.name)} ↗</a><button type="button" class="secondary" data-fallback>${fb?'Back to the online tool':esc(a.fallback.title)}</button></div><div id="labFallback" class="lab-fallback" ${fb?'':'hidden'}><strong>${esc(a.fallback.title)}</strong><ol>${a.fallback.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></div>${a.file?`<div class="dataset" data-dataset="${esc(a.file)}" data-readonly><p class="muted">Loading ${esc(a.file)}…</p></div>`:''}<div class="text-fields">${a.fields.map((f,i)=>`<label><span>${esc(f)}</span><textarea data-i="${i}" placeholder="Write what actually happened…">${esc(v[i]||'')}</textarea></label>`).join('')}</div></div>`}
if(a.kind==='testlog'&&a.columns)return `<div class="table-wrap"><table class="testlog-table"><thead><tr><th>#</th>${a.columns.map(c=>`<th>${esc(c[1])}</th>`).join('')}</tr></thead><tbody>${Array.from({length:a.rows},(_,i)=>{const r=v[i]||{};return `<tr><td>${i+1}</td>${a.columns.map(([k,l])=>`<td><input data-i="${i}" data-f="${esc(k)}" placeholder="${esc(l)}" aria-label="Row ${i+1} ${esc(l)}" value="${esc(r[k]||'')}"></td>`).join('')}</tr>`}).join('')}</tbody></table></div>`;
if(a.kind==='testlog')return `<div class="table-wrap"><table><thead><tr><th>#</th><th>Actual class</th><th>Prediction</th><th>Correct?</th><th>Observation</th></tr></thead><tbody>${Array.from({length:a.rows},(_,i)=>{const r=v[i]||{};return `<tr><td>${i+1}</td><td><select data-r="${i}" data-f="actual"><option></option>${a.classes.map(o=>`<option ${r.actual===o?'selected':''}>${o}</option>`).join('')}</select></td><td><select data-r="${i}" data-f="prediction"><option></option>${a.classes.map(o=>`<option ${r.prediction===o?'selected':''}>${o}</option>`).join('')}</select></td><td>${r.actual&&r.prediction?(r.actual===r.prediction?'✓':'✕'):''}</td><td><input data-r="${i}" data-f="note" value="${esc(r.note||'')}" placeholder="angle, light, background…"></td></tr>`}).join('')}</tbody></table></div>`;
if(a.kind==='prompt'){const b=v.builder||{},vs=v.versions||{},ex=v.extras||{};return `<div class="prompt-lab">${safetyHTML(a,v)}${a.builder?`<div class="prompt-builder"><div class="daymap-head">C-T-C-F BUILDER · CONTEXT · TASK · CONSTRAINTS · FORMAT</div><div class="prompt-builder-grid">${PROMPT_BUILDER.map(([k,l,hint])=>`<label><span>${l}</span><textarea data-builder="${k}" rows="2" placeholder="${esc(hint)}" aria-label="${l}">${esc(b[k]||'')}</textarea></label>`).join('')}</div><button id="composeV2" type="button" class="secondary">Compose v2</button><p class="muted">Joins the four parts, with a blank line between them, into the V2 prompt below. You can still edit it there.</p></div>`:''}${(a.versions||[]).map(([key,label])=>{const r=vs[key]||{};return `<div class="prompt-version"><strong>${esc(label)}</strong><div class="text-fields">${(a.fields||[]).map(([f,l])=>`<label><span>${esc(l)}</span><textarea data-version="${esc(key)}" data-field="${esc(f)}" placeholder="${f==='prompt'?'Paste the prompt exactly as you sent it…':'Write what actually happened…'}">${esc(r[f]||'')}</textarea></label>`).join('')}</div></div>`}).join('')}${Array.isArray(a.extras)&&a.extras.length?`<div class="text-fields prompt-extras">${a.extras.map((f,i)=>`<label><span>${esc(f)}</span><textarea data-extra="${i}" placeholder="Write in your own words…">${esc(ex[i]||'')}</textarea></label>`).join('')}</div>`:''}</div>`}
if(a.kind==='annotate')return `<div class="annotate-lab" data-annotate="${esc(a.file)}"><p class="muted">Loading ${esc(a.file)}…</p></div>`;
if(a.kind==='simulator'){const last=(Array.isArray(v.runs)?v.runs:[]).slice(-1)[0]||{},f=v.fields||{},removed=Boolean(last.removed);return `<div class="bias-sim"><p class="sim-scenario">${esc(a.scenario)}</p><div class="sim-controls">${(a.controls||[]).map(([k,l,min,max,step,def])=>{const val=Number.isFinite(last[k])?last[k]:def;return `<label><span>${esc(l)}</span><input type="range" data-sim="${esc(k)}" min="${min}" max="${max}" step="${step}" value="${val}" aria-label="${esc(l)}"><output data-sim-value="${esc(k)}">${val}%</output></label>`}).join('')}<label class="lab-ack"><input type="checkbox" data-sim="${esc(a.toggle[0])}" ${removed?'checked':''}> ${esc(a.toggle[1])}</label></div><table class="sim-results"><thead><tr><th>Group</th><th>Correct decisions</th></tr></thead><tbody><tr><th>Group A (20 applicants)</th><td id="simAccA">18/20 · 90%</td></tr><tr><th>Group B (20 applicants)</th><td id="simAccB"></td></tr><tr><th>Overall</th><td id="simOverall"></td></tr></tbody></table><button id="simRecord" type="button" class="secondary">Record this run</button><div class="findings"><strong>Recorded runs</strong><ol class="sim-runs">${simRunsHTML(s)}</ol></div><div class="text-fields">${(a.fields||[]).map(([k,l],i)=>`<label><span>${esc(l)}</span><textarea data-i="${i}" data-field="${esc(k)}" placeholder="Write what you actually saw…">${esc(f[k]||'')}</textarea></label>`).join('')}</div></div>`}
if(a.kind==='decision')return decisionLabHTML(s);
if(a.kind==='matrix'){const m=v.matrix||{};return `<div class="matrix-grid"><label><span>Actual Cup → Predicted Cup</span><input type="number" min="0" data-m="cc" value="${m.cc||0}"></label><label><span>Actual Cup → Predicted Bottle</span><input type="number" min="0" data-m="cb" value="${m.cb||0}"></label><label><span>Actual Bottle → Predicted Cup</span><input type="number" min="0" data-m="bc" value="${m.bc||0}"></label><label><span>Actual Bottle → Predicted Bottle</span><input type="number" min="0" data-m="bb" value="${m.bb||0}"></label></div><button id="calcMatrix" class="secondary">Calculate accuracy</button><div id="matrixResult" class="result"></div>`}return''}

// AI Adoption Decision Simulator (Chapter 7, b7s4). The branching graph, evidence cards and metric vectors are fixed curriculum data. Every node's vector is the whole projected or observed model week and replaces the previous one, so nothing accumulates, nothing is random, and no terminal node is the "right" answer.
const DECISION_ROWS=[['value','Value and cost','Released task capacity priced at the stated hourly value, less extra weekly cost. Not cash profit, wages saved or jobs lost.'],['tasks','Work allocation','Automatic, assisted and manual counts are disjoint and cover the same model week of requests.'],['safety','Wrong or unresolved outcomes','Service reliability failures in this exercise. Severity of harm is not estimated.'],['fairness','Group error rates','Group B is a support route, not a demographic label. The gap is percentage points, and one number does not settle fairness.'],['privacy','Added AI transcript storage','Days of new AI transcript storage only. The existing order records are unchanged, so 0 does not mean no personal data.'],['accountability','Who is accountable','A named role can correct, pause or stop the service. Using a supplier does not move that duty.'],['uncertainty','What stays uncertain','Modelled possibilities rest on the stated assumptions about demand, reliability, staffing and governance.'],['sustainability','Added AI energy use','An invented comparison index for added AI use, not measured kWh or carbon.']];
const dec1=n=>Number(n).toFixed(1),dec2=n=>Number(n).toFixed(2);
const decNode=(a,id)=>(a.nodes||[]).find(n=>n.id===id)||null;
const decCard=(a,id)=>(a.evidence||[]).find(e=>e.id===id)||null;
function decData(a,v){const d=v&&typeof v==='object'?v:{};return {scenarioId:a.scenario?.id,modelVersion:1,path:Array.isArray(d.path)?d.path:[],draft:{choiceId:'',evidenceId:'',reason:'',...(d.draft&&typeof d.draft==='object'?d.draft:{})},runs:Array.isArray(d.runs)?d.runs:[],futures:d.futures&&typeof d.futures==='object'?d.futures:{},fields:d.fields&&typeof d.fields==='object'?d.fields:{}}}
function decReplay(a,path){let node=decNode(a,a.start);if(!node)return null;const steps=[];for(const raw of (Array.isArray(path)?path:[])){if(!raw||typeof raw!=='object'||raw.nodeId!==node.id)return null;const edge=(node.choices||[]).find(c=>c.id===raw.choiceId);if(!edge)return null;const next=decNode(a,edge.next);if(!next)return null;steps.push({nodeId:node.id,node,choiceId:edge.id,label:edge.label,evidenceId:String(raw.evidenceId||''),reason:String(raw.reason||'')});node=next}return {steps,node}}
function decAvailable(a,rep){const out=[];for(const n of [decNode(a,a.start),...rep.steps.map(x=>x.node),rep.node])for(const id of (n?.evidenceIds||[]))if(!out.includes(id))out.push(id);return out}
function decVector(a,node){return node&&Array.isArray(node.metrics)?Object.fromEntries((a.metricKeys||[]).map((k,i)=>[k,Number(node.metrics[i])])):null}
function decBaseline(a){const base=a.scenario?.baseline||[];return Object.fromEntries((a.metricKeys||[]).map((k,i)=>[k,Number(base[i])]))}
function decDerive(a,m){const g=a.scenario?.groups||[],nA=Number(g[0]?.[2])||0,nB=Number(g[1]?.[2])||0,rate=Number(a.scenario?.hourValueEUR)||0,hoursReleased=decBaseline(a).humanHours-m.humanHours,rateA=m.wrongA/nA*100,rateB=m.wrongB/nB*100;return {...m,nA,nB,total:nA+nB,hoursReleased,capacityValueEUR:hoursReleased*rate-m.costEUR,manual:nA+nB-m.automated-m.assisted,wrongTotal:m.wrongA+m.wrongB,rateA,rateB,gap:Math.abs(rateB-rateA)}}
function decRun(a,run){if(!run||typeof run!=='object'||!Number.isInteger(run.id)||run.id<1)return null;const rep=decReplay(a,run.path);if(!rep||rep.steps.length!==2||(rep.node.choices||[]).length||run.terminalId!==rep.node.id)return null;const [first,second]=rep.steps,root=(decNode(a,a.start)||{}).evidenceIds||[];if(first.reason.trim().length<12||second.reason.trim().length<12)return null;if(!root.includes(first.evidenceId)||second.evidenceId!==(second.node.evidenceIds||[])[0])return null;return {id:run.id,start:first.choiceId,steps:rep.steps,terminalId:rep.node.id,node:rep.node,metrics:decVector(a,rep.node)}}
function decRuns(a,d){return d.runs.map(r=>decRun(a,r)).filter(Boolean)}
function decStage(a,node){return node.id===a.start?'Baseline observation':(node.choices||[]).length?'Fictional observation':'Modelled possibility'}
function decRunLine(a,r){const v=decDerive(a,r.metrics);return `Run ${r.id}: ${r.steps.map(x=>x.label).join(' → ')} → ${r.node.title} · value €${dec2(v.capacityValueEUR)} · wrong ${v.wrongTotal}/${v.total} (A ${v.wrongA}/${v.nA}, B ${v.wrongB}/${v.nB}) · retention ${v.retentionDays} days · energy ${v.energyUnits} units`}
function decCells(a,v){return {value:`${dec1(v.hoursReleased)} h released · €${dec2(v.costEUR)} extra cost · net capacity value €${dec2(v.capacityValueEUR)}`,tasks:`${v.automated} automatic · ${v.assisted} assisted · ${v.manual} manual of ${v.total}`,safety:`${v.wrongTotal}/${v.total} wrong or unresolved`,fairness:`A ${v.wrongA}/${v.nA} = ${dec2(v.rateA)}% · B ${v.wrongB}/${v.nB} = ${dec2(v.rateB)}% · gap ${dec2(v.gap)} percentage points`,privacy:`${v.retentionDays} days`,sustainability:`${v.energyUnits} index units`}}
function decEvidenceHTML(a,ids){return `<div class="decision-evidence"><strong>Evidence you can use so far</strong><ul>${ids.map(id=>{const e=decCard(a,id)||{};return `<li data-evidence="${esc(id)}"><b>${esc(id)}</b> <em>${esc(e.status||'')}</em><span>${esc(e.text||'')}</span></li>`}).join('')}</ul></div>`}
function decMetricsHTML(a,node){const start=decNode(a,a.start)||{},base=decCells(a,decDerive(a,decBaseline(a))),cur=decCells(a,decDerive(a,decVector(a,node)||decBaseline(a)));base.accountability=start.accountability;base.uncertainty=start.uncertainty;cur.accountability=node.accountability;cur.uncertainty=node.uncertainty;return `<div class="table-wrap"><table id="decisionMetrics" class="decision-metrics"><thead><tr><th>Dimension</th><th>Baseline · E1 observation</th><th>Now · ${esc(decStage(a,node))}</th></tr></thead><tbody>${DECISION_ROWS.map(([k,l,note])=>`<tr data-metric="${k}"><th>${esc(l)}<small>${esc(note)}</small></th><td>${esc(base[k])}</td><td>${esc(cur[k])}</td></tr>`).join('')}</tbody></table></div>`}
function decPathHTML(a,rep){return `<div class="decision-path-box"><strong>Your current path</strong><ol class="decision-path">${rep.steps.length?rep.steps.map(x=>`<li><b>${esc(x.node.title)}</b> → ${esc(x.label)} · cited ${esc(x.evidenceId)} · ${esc(x.reason)}</li>`).join(''):'<li class="muted">No choice recorded yet. Read the evidence, choose an approach and say why it follows from a card.</li>'}</ol></div>`}
function decRunsHTML(a,runs){return `<div class="findings"><strong>Recorded adoption paths</strong><ol class="decision-runs">${runs.length?runs.map(r=>`<li>${esc(decRunLine(a,r))}<ul>${r.steps.map(x=>`<li>${esc(x.label)} · ${esc(x.evidenceId)}: ${esc(x.reason)}</li>`).join('')}</ul></li>`).join(''):`<li class="muted">No paths recorded yet. Record at least ${a.minRuns||3} complete paths with different starting choices, including no deployment.</li>`}</ol></div>`}
function decFuturesHTML(a,d,runs){return `<div class="decision-futures"><strong>Your three possible futures</strong><p class="muted">Each future uses a different recorded path. You assign the label and write the scenario: nothing here is labelled from the numbers, and the next session adds the five-stakeholder analysis.</p>${(a.futureLabels||[]).map(([k,l])=>{const f=d.futures[k]||{};return `<label><span>${esc(l)}</span><select data-future="${esc(k)}" aria-label="${esc(l)} future: recorded path"><option value="">Choose a recorded path…</option>${runs.map(r=>`<option value="${r.id}" ${String(f.runId)===String(r.id)?'selected':''}>Run ${r.id}: ${esc(r.steps.map(x=>x.label).join(' → '))}</option>`).join('')}</select><textarea data-scenario="${esc(k)}" aria-label="${esc(l)} future: your scenario" placeholder="Technology change; human response; unintended consequence; what the case supports; what I am assuming about 2035…">${esc(f.text||'')}</textarea></label>`}).join('')}</div>`}
function decFieldsHTML(a,d){return `<div class="text-fields">${(a.fields||[]).map(([k,l])=>`<label><span>Comparison and uncertainty</span><textarea data-decision-field="${esc(k)}" placeholder="${esc(l)}">${esc(d.fields[k]||'')}</textarea></label>`).join('')}</div>`}
function decisionLabHTML(s){return `<div class="decision-lab">${decisionInnerHTML(s)}</div>`}
function decisionInnerHTML(s){const a=s.activity,d=decData(a,state.activity[s.id]),broken=Boolean(d.path.length&&!decReplay(a,d.path)),rep=decReplay(a,d.path)||{steps:[],node:decNode(a,a.start)},node=rep.node,avail=decAvailable(a,rep),runs=decRuns(a,d),open=Boolean((node.choices||[]).length),sig=JSON.stringify(d.path.map(x=>[x&&x.nodeId,x&&x.choiceId])),recorded=d.runs.some(r=>JSON.stringify((Array.isArray(r?.path)?r.path:[]).map(x=>[x&&x.nodeId,x&&x.choiceId]))===sig),need=rep.steps.length?(node.evidenceIds||[])[0]:'';
  return `<p class="decision-case"><b>${esc(a.scenario.title)}</b> · You advise as the ${esc(a.scenario.role)}. ${esc(a.scenario.brief)}</p><p class="muted decision-notice">Every person, count and consequence here is synthetic teaching data for one model week of ${a.scenario.groups.map(g=>`${esc(g[0])} ${esc(g[1])} ${g[2]}`).join(' · ')} requests. A revealed node is a fictional observation; a final outcome is a modelled possibility, not a measurement and not a forecast of 2035.</p>${decEvidenceHTML(a,avail)}<div class="decision-node" id="decisionNode" aria-live="polite"><h4 tabindex="-1">${esc(node.title)}</h4><p class="decision-stage">${esc(decStage(a,node))}${(node.evidenceIds||[]).length?` · evidence ${esc((node.evidenceIds||[]).join(', '))}`:''}</p><p>${esc(node.consequence)}</p><p><b>Accountable:</b> ${esc(node.accountability)}</p><p><b>Still uncertain:</b> ${esc(node.uncertainty)}</p></div>${decMetricsHTML(a,node)}${decPathHTML(a,rep)}<div class="decision-controls">${open?`<fieldset class="decision-choices"><legend>${rep.steps.length?'Choose what happens next':'Choose an adoption approach'}</legend>${(node.choices||[]).map(c=>`<label><input type="radio" name="decisionChoice" data-choice="${esc(c.id)}" value="${esc(c.id)}" ${d.draft.choiceId===c.id?'checked':''}><span>${esc(c.label)}</span></label>`).join('')}</fieldset><label><span>Evidence you are citing${need?` · use ${esc(need)}, the card this route has just revealed`:''}</span><select id="decisionEvidence"><option value="">Choose an evidence card…</option>${avail.map(id=>`<option value="${esc(id)}" ${d.draft.evidenceId===id?'selected':''}>${esc(id)} — ${esc((decCard(a,id)||{}).status||'')}</option>`).join('')}</select></label><label><span>Why does this option follow from that evidence, and what does the alternative lose?</span><textarea id="decisionReason" placeholder="Name what the card shows, then what you are giving up…">${esc(d.draft.reason||'')}</textarea></label><button id="decisionChoose" type="button" class="primary">Choose and reveal consequences</button>`:`<button id="decisionRecord" type="button" class="primary" ${recorded||d.runs.length>=8?'disabled':''}>Record this path</button>`}${(rep.steps.length||broken)?'<button id="decisionRestart" type="button" class="secondary">Try another starting choice</button>':''}</div><p class="result" id="decisionFeedback" aria-live="polite"></p>${decRunsHTML(a,runs)}${decFuturesHTML(a,d,runs)}${decFieldsHTML(a,d)}`}
function decisionEvidenceItems(b){return b.sessions.filter(s=>s.activity.kind==='decision').flatMap(s=>{const a=s.activity,d=decData(a,state.activity[s.id]),runs=decRuns(a,d),items=runs.map(r=>[`Recorded adoption path ${r.id}`,`${decRunLine(a,r)} · ${r.steps.map(x=>`${x.evidenceId}: ${x.reason}`).join(' | ')}`]);for(const [k,l] of (a.futureLabels||[])){const f=d.futures[k]||{};if(String(f.text||'').trim())items.push([`${l} future · run ${f.runId==null?'—':f.runId}`,String(f.text).trim()])}for(const [k] of (a.fields||[]))if(String(d.fields[k]||'').trim())items.push(['Comparison and uncertainty',String(d.fields[k]).trim()]);return items})}
function stageEvidenceItems(b){const stageIds=new Set((b?.lab?.stages||[]).map(x=>x[1]));return (b?.sessions||[]).filter(s=>s.activity.kind==='lab'||(stageIds.has(s.id)&&['textfields','chain','testlog'].includes(s.activity.kind))).flatMap(s=>{const a=s.activity,v=state.activity[s.id]||{};if(a.fields)return a.fields.map((f,i)=>[f,String(v[i]||'').trim()]).filter(x=>x[1]);const cols=a.columns||[],rows=Object.keys(v).filter(k=>/^\d+$/.test(k)).sort((x,y)=>x-y).map(k=>v[k]).filter(r=>r&&typeof r==='object');const lines=rows.map(r=>cols.map(([k,l])=>String(r[k]||'').trim()?`${l}: ${String(r[k]).trim()}`:'').filter(Boolean).join(' · ')).filter(Boolean);return lines.length?[[s.title,lines.join(' | ')]]:[]})}
function labEvidenceHTML(b){const items=[...stageEvidenceItems(b),...decisionEvidenceItems(b)];if(!items.length)return '';return `<div class="lab-evidence"><strong>Your Experience Lab evidence</strong><p class="muted">Use what you actually observed in the lab to support your answers.</p><dl>${items.map(([f,v])=>`<div><dt>${esc(f)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl></div>`}
function capstoneHTML(){
  if(!activeBlock||!blockDone(activeBlock))return '';
  const cap=CAPSTONES[activeBlock.id];
  if(!cap)return '';
  const saved=state.chapterAssessments?.[activeBlock.id];
  if(saved?.submittedAt)return `<section class="assessment-card chapter-capstone"><div class="eyebrow">CHAPTER ASSESSMENT · COMPLETE</div><h3>${esc(cap.title)}</h3><p><strong>${esc(saved.level||'Evaluated')}</strong> · Your ${esc(activeBlock.badge)} badge is confirmed.</p><p>The teacher can review or override this formative judgement in the admin dashboard.</p></section>`;
  if(!user)return `<section class="assessment-card chapter-capstone"><div class="eyebrow">CHAPTER ASSESSMENT · READY</div><h3>${esc(cap.title)}</h3><p>${esc(cap.brief)}</p><p><strong>Sign in with Google to submit the chapter assessment and unlock the next chapter.</strong></p></section>`;
  return `<section class="assessment-card chapter-capstone"><div class="eyebrow">CHAPTER ASSESSMENT · APPLIED CHALLENGE</div><h3>${esc(cap.title)}</h3><p>${esc(cap.brief)}</p><p class="muted">This is a work-like challenge, not a recall quiz. Use what you learned from the chapter and explain your judgement.</p>${selfCheckHTML(activeBlock)}${levelUpHTML(activeBlock)}${labEvidenceHTML(activeBlock)}${cap.prompts.map((p,i)=>`<label class="record"><span>${esc(p)}</span><textarea data-capstone="${i}" placeholder="Explain your decision and evidence in your own words…"></textarea></label>`).join('')}<button id="submitCapstone" class="primary">Submit chapter assessment</button><div id="capstoneFeedback" class="result"></div></section>`;
}

function renderChapterCapstone(){const existing=document.getElementById('chapterCapstoneHost');if(existing)existing.remove();if(!activeBlock||!blockDone(activeBlock))return;const host=document.createElement('div');host.id='chapterCapstoneHost';host.innerHTML=capstoneHTML();document.getElementById('lessonPanel').appendChild(host);const btn=document.getElementById('submitCapstone');if(btn)btn.onclick=submitChapterAssessment}

async function submitChapterAssessment(){
  if(cloudError){feedback('capstoneFeedback','Cloud sync is unavailable right now, so the assessment cannot be submitted. Reload the page to reconnect, then submit again.','warn');return}
  const cap=CAPSTONES[activeBlock.id];
  const answers={};
  document.querySelectorAll('[data-capstone]').forEach(x=>answers[x.dataset.capstone]=x.value.trim());
  if(Object.values(answers).some(v=>String(v).length<25)){feedback('capstoneFeedback','Develop each answer a little further so your reasoning and evidence are clear.','warn');return}
  const btn=document.getElementById('submitCapstone');btn.disabled=true;feedback('capstoneFeedback','Evaluating your applied challenge…');
  try{
    await api('progress',{method:'PUT',body:JSON.stringify({state})});
    const data=await api(`chapter-assessment/${activeBlock.id}`,{method:'POST',body:JSON.stringify({answers})});
    state.chapterAssessments[activeBlock.id]={submittedAt:data.assessment.submittedAt,level:data.assessment.effectiveLevel||data.assessment.suggestedLevel,teacherLevel:data.assessment.teacherLevel||null,suggestedLevel:data.assessment.suggestedLevel,score:data.assessment.suggestedScore};
    reconcileBadges();
    await api('progress',{method:'PUT',body:JSON.stringify({state})});
    saveLocal();renderHome();renderChapterCapstone();
  }catch(err){feedback('capstoneFeedback',err.message,'warn');btn.disabled=false}
}

function renderLesson(){const s=activeSession,complete=state.completed.includes(s.id);document.getElementById('lessonPanel').innerHTML=`<div class="lesson-title"><div><div class="eyebrow">${esc(s.type)} · ${s.minutes} MIN</div><h2>${esc(s.title)}</h2><p>${esc(s.intro)}</p></div>${complete?'<span class="complete-chip">✓ Evidence complete</span>':''}</div>${studyHTML(s)}<section class="activitybox"><div class="eyebrow">TRY · LEARN BY DOING</div><h3>${esc(s.activity.title)}</h3><p>${esc(s.activity.instructions)}</p>${activityHTML(s)}<div id="activityFeedback" class="result"></div></section><section class="reflectbox"><div class="eyebrow">REFLECT · YOUR WORDS</div><h3>Explain what you understood</h3><p>${esc(s.reflection)}</p><textarea id="reflectionText" placeholder="Use the study material to help you think, then explain the idea in your own words.">${esc(state.reflections[s.id]||'')}</textarea></section><div class="lesson-actions"><button id="saveSession" class="primary">${complete?'Update evidence':'Complete session'}</button><button id="hintBtn" class="secondary">Give me a hint</button></div><div id="lessonFeedback" class="result"></div>`;wireActivity(s);document.getElementById('hintBtn').onclick=()=>feedback('lessonFeedback','Use the key words above as a structure. Point to one concrete example, then explain what it shows.','warn');document.getElementById('saveSession').onclick=()=>saveSession(s);renderChapterCapstone()}

// Decision simulator wiring: one edge is committed at a time, only from the node the saved path actually reaches, and every draft, edge, run, canvas and comparison change is persisted through the existing state/sync mechanism.
function wireDecision(s,host){const a=s.activity,read=()=>decData(a,state.activity[s.id]),save=next=>{state.activity[s.id]={...(state.activity[s.id]||{}),...read(),...next};scheduleSync()},paint=focus=>{host.innerHTML=decisionInnerHTML(s);bind();if(focus){const h=host.querySelector('#decisionNode h4');if(h&&h.focus)h.focus()}},bind=()=>{const choose=host.querySelector('#decisionChoose'),record=host.querySelector('#decisionRecord'),restart=host.querySelector('#decisionRestart'),cite=host.querySelector('#decisionEvidence'),reason=host.querySelector('#decisionReason');host.querySelectorAll('input[name="decisionChoice"]').forEach(x=>x.onchange=()=>save({draft:{...read().draft,choiceId:x.value}}));if(cite)cite.onchange=()=>save({draft:{...read().draft,evidenceId:cite.value}});if(reason)reason.oninput=()=>save({draft:{...read().draft,reason:reason.value}});if(choose)choose.onclick=()=>{const d=read(),rep=decReplay(a,d.path);if(!rep)return feedback('decisionFeedback','Your saved path no longer matches this simulator. Restart to begin a new path; your recorded runs are kept.','warn');const node=rep.node,need=rep.steps.length?(node.evidenceIds||[])[0]:'';if(!(node.choices||[]).some(c=>c.id===d.draft.choiceId))return feedback('decisionFeedback','Choose one of the options first.','warn');if(!decAvailable(a,rep).includes(d.draft.evidenceId))return feedback('decisionFeedback','Cite one of the evidence cards you can actually see on this path.','warn');if(need&&d.draft.evidenceId!==need)return feedback('decisionFeedback',`Cite ${need} here: the card this route has just revealed.`,'warn');if(String(d.draft.reason||'').trim().length<12)return feedback('decisionFeedback','Write at least 12 characters on why this option follows from that evidence.','warn');save({path:[...d.path,{nodeId:node.id,choiceId:d.draft.choiceId,evidenceId:d.draft.evidenceId,reason:String(d.draft.reason).trim()}],draft:{choiceId:'',evidenceId:'',reason:''}});feedback('decisionFeedback','');paint(true)};if(record)record.onclick=()=>{const d=read(),rep=decReplay(a,d.path);if(!rep||(rep.node.choices||[]).length)return feedback('decisionFeedback','Follow a path to a final outcome before recording it.','warn');const sig=JSON.stringify(d.path.map(x=>[x.nodeId,x.choiceId]));if(d.runs.some(r=>JSON.stringify((Array.isArray(r?.path)?r.path:[]).map(x=>[x&&x.nodeId,x&&x.choiceId]))===sig))return feedback('decisionFeedback','You have already recorded this exact path. Restart and take a different starting choice.','warn');if(d.runs.length>=8)return feedback('decisionFeedback','Eight recorded paths is the limit of this simulator.','warn');const id=d.runs.reduce((n,r)=>Math.max(n,Number(r?.id)||0),0)+1;save({runs:[...d.runs,{id,path:d.path.map(x=>({...x})),terminalId:rep.node.id,metrics:decVector(a,rep.node)}]});feedback('decisionFeedback',`Recorded as run ${id}. Restart to follow a different starting choice.`,'ok');paint()};if(restart)restart.onclick=()=>{save({path:[],draft:{choiceId:'',evidenceId:'',reason:''}});feedback('decisionFeedback','');paint(true)};host.querySelectorAll('select[data-future]').forEach(x=>x.onchange=()=>{const d=read(),k=x.dataset.future;save({futures:{...d.futures,[k]:{...(d.futures[k]||{}),runId:x.value?Number(x.value):null}}})});host.querySelectorAll('textarea[data-scenario]').forEach(x=>x.oninput=()=>{const d=read(),k=x.dataset.scenario;save({futures:{...d.futures,[k]:{...(d.futures[k]||{}),text:x.value}}})});host.querySelectorAll('textarea[data-decision-field]').forEach(x=>x.oninput=()=>{const d=read();save({fields:{...d.fields,[x.dataset.decisionField]:x.value}})})};bind()}
function wireActivity(s){const panel=document.getElementById('lessonPanel');panel.querySelectorAll('[data-i]').forEach(x=>!x.closest('.bias-sim')&&x.addEventListener(x.tagName==='TEXTAREA'||x.tagName==='INPUT'?'input':'change',()=>{const a=state.activity[s.id]||{};if(x.dataset.f){const i=x.dataset.i;a[i]=a[i]||{};a[i][x.dataset.f]=x.value}else a[x.dataset.i]=x.value;state.activity[s.id]=a;scheduleSync()}));panel.querySelectorAll('[data-r]').forEach(x=>x.addEventListener(x.tagName==='INPUT'?'input':'change',()=>{const a=state.activity[s.id]||{},i=x.dataset.r;a[i]=a[i]||{};a[i][x.dataset.f]=x.value;state.activity[s.id]=a;scheduleSync();if(s.activity.kind==='testlog')renderLesson()}));const ds=panel.querySelector('[data-dataset]');if(ds)wireDataset(s,ds);const an=panel.querySelector('[data-annotate]');if(an)wireAnnotate(s,an);const dl=panel.querySelector('.decision-lab');if(dl)wireDecision(s,dl);const sim=panel.querySelector('.bias-sim');if(sim){const cur=()=>state.activity[s.id]=state.activity[s.id]||{};const read=()=>{const o={};sim.querySelectorAll('input[type=range][data-sim]').forEach(x=>o[x.dataset.sim]=Number(x.value));o.removed=sim.querySelector('input[type=checkbox][data-sim="removed"]').checked;return o};const show=()=>{const o=read(),r=simModel(o.shareB,o.proxy,o.removed);sim.querySelectorAll('[data-sim-value]').forEach(x=>x.textContent=`${o[x.dataset.simValue]}%`);sim.querySelector('#simAccA').textContent=`${r.correctA}/20 · ${simPct(r.correctA/20)}%`;sim.querySelector('#simAccB').textContent=`${r.correctB}/20 · ${simPct(r.correctB/20)}%`;sim.querySelector('#simOverall').textContent=`${r.correctA+r.correctB}/40 · ${simPct(r.overall)}%`};show();sim.querySelectorAll('input[data-sim]').forEach(x=>x.oninput=show);const list=sim.querySelector('.sim-runs');sim.querySelector('#simRecord').onclick=()=>{const o=read(),r=simModel(o.shareB,o.proxy,o.removed),a=cur();a.runs=[...(Array.isArray(a.runs)?a.runs:[]),{shareB:o.shareB,proxy:o.proxy,removed:o.removed,correctA:r.correctA,correctB:r.correctB,overall:r.overall}];list.innerHTML=simRunsHTML(s);feedback('activityFeedback',`Run ${a.runs.length} recorded. Change one setting, watch Group B, then record again.`,'ok');scheduleSync()};sim.querySelectorAll('textarea[data-i]').forEach(x=>x.oninput=()=>{const a=cur();a.fields={...(a.fields||{}),[x.dataset.field]:x.value};scheduleSync()})}const ack=panel.querySelector('[data-ack]');if(ack)ack.onchange=()=>{state.activity[s.id]={...(state.activity[s.id]||{}),ack:ack.checked};const link=document.getElementById('labToolLink');link.classList.toggle('disabled',!ack.checked);link.setAttribute('aria-disabled',ack.checked?'false':'true');scheduleSync()};const fbBtn=panel.querySelector('[data-fallback]');if(fbBtn)fbBtn.onclick=()=>{const cur=state.activity[s.id]||{},next=cur.mode==='fallback'?'tool':'fallback';state.activity[s.id]={...cur,mode:next};document.getElementById('labFallback').hidden=next!=='fallback';fbBtn.textContent=next==='fallback'?'Back to the online tool':s.activity.fallback.title;scheduleSync()};const pl=panel.querySelector('.prompt-lab');if(pl){const cur=()=>state.activity[s.id]=state.activity[s.id]||{};pl.querySelectorAll('[data-builder]').forEach(x=>x.oninput=()=>{const a=cur();a.builder={...(a.builder||{}),[x.dataset.builder]:x.value};scheduleSync()});pl.querySelectorAll('textarea[data-version][data-field]').forEach(x=>x.oninput=()=>{const a=cur(),k=x.dataset.version;a.versions=a.versions||{};a.versions[k]={...(a.versions[k]||{}),[x.dataset.field]:x.value};scheduleSync()});pl.querySelectorAll('[data-extra]').forEach(x=>x.oninput=()=>{const a=cur();a.extras={...(a.extras||{}),[x.dataset.extra]:x.value};scheduleSync()});const compose=pl.querySelector('#composeV2');if(compose)compose.onclick=()=>{const a=cur(),b=a.builder||{},text=PROMPT_BUILDER.map(([k])=>String(b[k]||'').trim()).filter(Boolean).join('\n\n');const ta=pl.querySelector('textarea[data-version="v2"][data-field="prompt"]');if(!ta)return;if(ta.value.trim()&&!confirm('Replace the V2 prompt you already wrote?'))return;if(!text){feedback('activityFeedback','Fill in at least one of the four parts first.','warn');return}ta.value=text;a.versions=a.versions||{};a.versions.v2={...(a.versions.v2||{}),prompt:text};feedback('activityFeedback','Composed v2 from your four parts. Send it to the tool, then record what came back.','ok');ta.focus();scheduleSync()}}const single=panel.querySelector('[data-single]');if(single)single.oninput=e=>{state.activity[s.id]={...(state.activity[s.id]||{}),text:e.target.value};scheduleSync()};panel.querySelectorAll('[data-m]').forEach(x=>x.oninput=()=>{const a=state.activity[s.id]||{};a.matrix=a.matrix||{};a.matrix[x.dataset.m]=Math.max(0,Number(x.value)||0);state.activity[s.id]=a;scheduleSync()});const calc=document.getElementById('calcMatrix');if(calc)calc.onclick=()=>{const m=(state.activity[s.id]||{}).matrix||{},total=(m.cc||0)+(m.cb||0)+(m.bc||0)+(m.bb||0),correct=(m.cc||0)+(m.bb||0);document.getElementById('matrixResult').textContent=total?`Accuracy: ${Math.round(correct/total*100)}% (${correct}/${total} correct)`:'Enter your four counts first.'}}
function feedback(id,text,kind=''){const e=document.getElementById(id);if(!e)return;e.textContent=text;e.className='result '+kind}
// Two Chapter 8 rules live inside activityReady: its build lab makes AI optional, so the non-AI fallback route completes
// with the tool never acknowledged (labs whose fallback is a sample download, Chapters 4 and 6, still require the
// acknowledgement on both routes), and a risk register whose residual column says “none” is not an answer, because the book's point is
// that something always remains. Both are written inline: the chapter tests run this function as a single standalone line.
function activityReady(s){const a=s.activity,v=state.activity[s.id]||{};if(a.kind==='chain'&&(a.columns||[]).some(c=>c[0]==='residual')){const keys=a.columns.map(c=>c[0]);return Object.values(v).filter(x=>x&&keys.every(k=>{const text=String(x[k]||'').trim();return text&&!(k==='residual'&&/^(?:none|n\/?a|nothing|nil|no)\.?$/i.test(text))})).length>=(a.minRows||a.rows||1)}if(a.kind==='quiz')return a.items.every((_,i)=>v[i]);if(a.kind==='daymap'){const rows=Object.values(v).filter(x=>x&&x.service);const full=rows.filter(x=>x.input&&x.action&&x.output&&x.benefit&&x.risk);return rows.length>=5&&full.length>=2}if(a.kind==='textfields')return a.fields.every((_,i)=>String(v[i]||'').trim().length>=(Array.isArray(a.minLengths)&&Number.isFinite(a.minLengths[i])?a.minLengths[i]:12));if(a.kind==='external')return String(v.text||'').trim().length>=40;if(a.kind==='annotate'){const m=Array.isArray(v.marks)?v.marks:[];return m.length>=(a.minMarks||6)&&m.every(x=>String(x?.note||'').trim().length>=8)&&new Set(m.map(x=>x.type)).size>=3&&(Array.isArray(a.requiredMarks)?a.requiredMarks:[]).every(t=>m.some(x=>x.type===t))}if(a.kind==='simulator'){const runs=Array.isArray(v.runs)?v.runs:[],f=v.fields||{};return runs.length>=(a.minRuns||2)&&runs.some(r=>runs.some(q=>q.shareB!==r.shareB||q.proxy!==r.proxy||Boolean(q.removed)!==Boolean(r.removed)))&&(a.fields||[]).every(([k])=>String(f[k]||'').trim().length>=12)}if(a.kind==='decision'){const d=decData(a,v),runs=decRuns(a,d),min=a.minRuns||3,byId=new Map(runs.map(r=>[r.id,r]));if(runs.length<min)return false;const starts=new Set(runs.map(r=>r.start));if(starts.size<min||!(a.requiredStarts||[]).every(x=>starts.has(x)))return false;const picked=(a.futureLabels||[]).map(([k])=>d.futures[k]||{});if(picked.some(f=>!byId.has(f.runId)||String(f.text||'').trim().length<40))return false;const ids=picked.map(f=>f.runId),fs=ids.map(id=>byId.get(id).start);if(new Set(ids).size!==ids.length||new Set(fs).size!==fs.length||!(a.requiredStarts||[]).every(x=>fs.includes(x)))return false;return (a.fields||[]).every(([k])=>String(d.fields[k]||'').trim().length>=12)}if(a.kind==='lab')return Boolean(v.ack)&&a.fields.every((_,i)=>String(v[i]||'').trim().length>=12);if(a.kind==='testlog'){if(a.columns){const keys=a.columns.map(c=>c[0]);return Object.values(v).filter(x=>x&&keys.every(k=>String(x[k]||'').trim())).length>=(a.minRows||a.rows||3)}return Array.from({length:a.rows},(_,i)=>v[i]).every(r=>r?.actual&&r?.prediction)}if(a.kind==='chain'){const keys=(a.columns||[]).map(c=>c[0]);const full=Object.values(v).filter(x=>x&&keys.every(k=>String(x[k]||'').trim()));return full.length>=(a.minRows||a.rows||1)}if(a.kind==='dataset'){const f=(Array.isArray(v.findings)?v.findings:[]).filter(x=>String(x?.note||'').trim().length>=12);return f.length>=(a.minFindings||5)&&new Set(f.map(x=>x.issue)).size>=3&&(Array.isArray(a.requiredIssues)?a.requiredIssues:[]).every(t=>f.some(x=>x.issue===t))}if(a.kind==='matrix'){const m=v.matrix||{},total=(m.cc||0)+(m.cb||0)+(m.bc||0)+(m.bb||0);return total>0}if(a.kind==='prompt'){const vs=v.versions||{},ex=v.extras||{};const len=(r,k)=>String(r?.[k]||'').trim().length;return (a.versions||[]).every(([k])=>len(vs[k],'prompt')>=20&&len(vs[k],'output')>=20&&len(vs[k],'better')>=12)&&(Array.isArray(a.extras)?a.extras:[]).every((_,i)=>String(ex[i]||'').trim().length>=12)}return true}
// A rejected row needs to say which rule it broke. The residual rule is the one a student cannot guess from a
// generic message, because a blank and a considered "none" look equally finished to them.
function activityBlocker(s){const a=s.activity,v=state.activity[s.id]||{};
if(a.kind==='lab'&&!v.ack)return 'Read the safety notes and tick the box before recording your evidence. That applies on the fallback route too.';
if(a.kind==='chain'&&(a.columns||[]).some(c=>c[0]==='residual')&&Object.values(v).some(r=>r&&/^(none|n\/a|nothing)\.?$/i.test(String(r.residual||'').trim())))return 'Every row needs a residual. "None" is not accepted: something always remains after a safeguard.';
return ''}
function saveSession(s){const reflection=document.getElementById('reflectionText').value.trim();if(!activityReady(s)){feedback('lessonFeedback',activityBlocker(s)||'Finish the required activity evidence before completing this session.','warn');return}if(reflection.length<35){feedback('lessonFeedback','Add a little more reasoning in your own words (at least 35 characters).','warn');return}state.reflections[s.id]=reflection;if(!state.completed.includes(s.id))state.completed.push(s.id);scheduleSync();renderSessionNav();renderHome();const done=blockDone(activeBlock);feedback('lessonFeedback',done?'Chapter practical work complete. Your chapter assessment is now ready below.':'Evidence saved. Session complete.','ok');const next=activeBlock.sessions.find(x=>!state.completed.includes(x.id));const goNext=()=>{activeSession=next;renderSessionNav();renderLesson()};if(!next)renderChapterCapstone();else if(!user)setTimeout(goNext,450);else{const host=document.getElementById('lessonFeedback');let btn=document.getElementById('nextSession');if(!btn){btn=document.createElement('button');btn.id='nextSession';btn.className='primary next-session';host.insertAdjacentElement('afterend',btn)}btn.textContent=`Next: ${next.title} →`;btn.onclick=goNext}}

// Phase 10 · ADR-008. Field/column-labelled evidence for the portfolio export, one array entry per activity item.
// Only the shapes the curriculum actually uses are handled; anything else contributes no evidence rather than a raw dump.
function chapterEvidenceItems(s){const a=s.activity,v=state.activity[s.id];if(!v||typeof v!=='object')return[];const rows=()=>Object.keys(v).filter(k=>/^\d+$/.test(k)).sort((x,y)=>x-y).map(k=>v[k]);
  if(a.kind==='quiz')return a.items.map((it,i)=>({label:it[0],value:v[i]})).filter(x=>x.value);
  if(a.kind==='daymap')return rows().filter(r=>r&&r.service).map((r,i)=>({label:`Row ${i+1}`,value:['service','input','action','output','benefit','risk'].map(f=>r[f]).filter(Boolean).join(' · ')}));
  if(a.kind==='chain'){const cols=a.columns||[];return rows().filter(r=>r&&typeof r==='object').map((r,i)=>({label:`Row ${i+1}`,value:cols.map(([k,l])=>r[k]?`${l}: ${r[k]}`:'').filter(Boolean).join(' · ')})).filter(x=>x.value)}
  if(a.kind==='textfields'||a.kind==='lab')return a.fields.map((f,i)=>({label:f,value:v[i]})).filter(x=>x.value);
  if(a.kind==='external')return v.text?[{label:'Experiment record',value:v.text}]:[];
  if(a.kind==='dataset')return (Array.isArray(v.findings)?v.findings:[]).map((f,i)=>({label:`Finding ${i+1} (${f.issue} at ${f.target})`,value:f.note}));
  if(a.kind==='annotate')return (Array.isArray(v.marks)?v.marks:[]).map((m,i)=>({label:`Mark ${i+1} (${m.type} at sentence ${m.sentence})`,value:m.note}));
  if(a.kind==='testlog'){if(a.columns)return rows().filter(r=>r&&typeof r==='object').map((r,i)=>({label:`Row ${i+1}`,value:a.columns.map(([k,l])=>r[k]?`${l}: ${r[k]}`:'').filter(Boolean).join(' · ')})).filter(x=>x.value);return rows().filter(r=>r&&r.actual).map((r,i)=>({label:`Row ${i+1}`,value:`Actual ${r.actual} · Predicted ${r.prediction}${r.note?` · ${r.note}`:''}`}))}
  if(a.kind==='prompt'){const vs=v.versions||{},ex=v.extras||{};const items=(a.versions||[]).flatMap(([k,label])=>(a.fields||[]).map(([f,l])=>({label:`${label} — ${l}`,value:(vs[k]||{})[f]})).filter(x=>x.value));return [...items,...(a.extras||[]).map((f,i)=>({label:f,value:ex[i]})).filter(x=>x.value)]}
  if(a.kind==='simulator'){const f=v.fields||{};return (a.fields||[]).map(([k,l])=>({label:l,value:f[k]})).filter(x=>x.value)}
  if(a.kind==='matrix'){const m=v.matrix||{};return Object.values(m).some(Boolean)?[{label:'Confusion matrix',value:`Cup→Cup ${m.cc||0}, Cup→Bottle ${m.cb||0}, Bottle→Cup ${m.bc||0}, Bottle→Bottle ${m.bb||0}`}]:[]}
  return[]}
// The chapter assessment level is teacher-set where a review has happened, otherwise the system's suggestion;
// today's saved record only carries the merged, effective level, so the export labels what it actually has.
function chapterAssessmentData(b){const rec=state.chapterAssessments?.[b.id];if(!rec?.submittedAt)return null;return {level:rec.level,teacherLevel:rec.teacherLevel||null,suggestedLevel:rec.suggestedLevel||null}}
function slug(v){return (String(v||'student').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'')||'student')}
function downloadHTML(filename,html){const blob=new Blob([html],{type:'text/html'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url)}
async function portfolioProjects(){if(!user)return {projects:{},failed:[]};const out={},failed=[];await Promise.all(COURSE.blocks.map(async b=>{try{const d=await api('projects/'+b.id);const w=d?.project?.submittedSnapshot||d?.project?.workspace;if(!w)return;const deliverables=(w.evidence||[]).map(e=>[String(e.label||'').trim(),String(e.note||'').trim()]).filter(x=>x[0]&&x[1]);const rec=String(w.finalRecommendation||'').trim();if(deliverables.length||rec)out[b.id]={deliverables,finalRecommendation:rec,status:d?.project?.status||''}}catch(err){if(err?.status&&err.status!==404&&err.status!==409)failed.push(b.number)}}));return {projects:out,failed}}
function portfolioExportData(projects={}){reconcileBadges();return {displayName:user?.displayName||'Student',programmeName:PROGRAMME_NAME,exportDate:new Date().toISOString().slice(0,10),completionPct:pct(),chapters:COURSE.blocks.map(b=>({number:b.number,title:b.title,badge:b.badge,badgeEarned:blockQualified(b),assessment:chapterAssessmentData(b),project:projects[b.id]||null,sessions:b.sessions.filter(s=>state.completed.includes(s.id)).map(s=>({title:s.title,reflection:state.reflections[s.id]||''})),evidence:[...b.sessions.filter(s=>state.completed.includes(s.id)).flatMap(chapterEvidenceItems),...decisionEvidenceItems(b).map(([label,value])=>({label,value}))]}))}}
async function exportPortfolio(){const btn=document.getElementById('exportPortfolio');if(btn)btn.disabled=true;setSync('Preparing your portfolio…');
  try{const {projects,failed}=await portfolioProjects();
    if(failed.length&&!confirm(`Your project work for chapter ${failed.join(', ')} could not be loaded, so it would be missing from the export. Export anyway?`))return;
    downloadHTML(`${slug(user?.displayName)}-portfolio.html`,buildPortfolioExport(portfolioExportData(projects)));
    setSync(failed.length?'Exported without some project work':'Portfolio exported',failed.length?'error':'online');
  }catch(err){console.error(err);setSync('Export failed. Try again.','error')}finally{if(btn)btn.disabled=false}}
function exportCoordinatorSummary(){downloadHTML(`${slug(user?.displayName)}-coordinator-summary.html`,buildCoordinatorSummary(portfolioExportData()))}

function renderPortfolio(){reconcileBadges();document.getElementById('portfolioPct').textContent=pct()+'%';document.getElementById('portfolioSessions').textContent=state.completed.length;document.getElementById('portfolioBadges').textContent=state.badges.length;document.getElementById('portfolioContent').innerHTML=(COURSE.blocks.every(b=>blockQualified(b))?`<p class="programme-complete">Badge earned: ${esc(COURSE.blocks[COURSE.blocks.length-1].badge)} ✓ · Programme complete</p>`:'')+COURSE.blocks.map(b=>`<section class="portfolio-block"><div class="eyebrow">CHAPTER ${b.number}</div><h2>${esc(b.title)}</h2><p><strong>Mission:</strong> ${esc(b.mission)}</p>${blockQualified(b)?`<span class="complete-chip">🏅 ${esc(b.badge)} · chapter assessment complete</span>`:blockDone(b)?'<span class="muted">Practical work complete · chapter assessment pending</span>':''}${b.sessions.filter(s=>state.completed.includes(s.id)).map(s=>`<article><h3>${esc(s.title)}</h3><p><strong>My reflection:</strong> ${esc(state.reflections[s.id]||'')}</p></article>`).join('')}</section>`).join('')}

async function signIn(){try{setSync('Opening Google…');await oauthLogin('google')}catch(err){setSync('Google sign-in unavailable','error');console.error(err)}}
async function signOut(){try{await logout()}catch(err){console.error(err)}user=null;cloudError=null;state=loadLocal(ANON_KEY);reconcileBadges();setSync('Local mode');renderHome();show('homeView')}
// Cloud state arrives after the first paint. A learner already looking at the Portfolio would otherwise keep
// seeing zeros, and an export taken from that screen would contain none of their work.
function refreshOpenView(){const pv=document.getElementById('portfolioView');if(pv&&!pv.classList.contains('hidden'))renderPortfolio()}
async function initAuth(){state=loadLocal(ANON_KEY);try{await handleAuthCallback()}catch(err){console.warn('Identity callback',err)}let identityUser=null;try{identityUser=await getUser()}catch(err){console.warn('Identity lookup',err)}if(!identityUser){reconcileBadges();setSync('Local mode');renderHome();return}try{const session=await api('session');user=session.student;cloudError=null;const cloud=sanitizeState(session.state);const anon=loadLocal(ANON_KEY);if(isEmpty(cloud)&&!isEmpty(anon)){state=anon;reconcileBadges();saveLocal();await api('progress',{method:'PUT',body:JSON.stringify({state})});localStorage.removeItem(ANON_KEY)}else{state=cloud;reconcileBadges();saveLocal()}setSync('Cloud synced','online')}catch(err){console.error('Session restore failed',err.status||'',err);user={id:identityUser.id,email:identityUser.email,displayName:String(identityUser.userMetadata?.full_name||identityUser.email||'Student').slice(0,80)};cloudError=err.status?`HTTP ${err.status}: ${err.message}`:(err.message||'network error');state=loadLocal(ANON_KEY);reconcileBadges();setSync('Signed in · cloud sync unavailable','error')}renderHome();refreshOpenView()}

function bind(){document.getElementById('homeBtn').onclick=()=>{renderHome();show('homeView')};document.getElementById('backBtn').onclick=()=>{renderHome();show('homeView')};document.getElementById('portfolioBack').onclick=()=>{renderHome();show('homeView')};document.getElementById('portfolioBtn').onclick=()=>{renderPortfolio();show('portfolioView')};document.getElementById('exportPortfolio').onclick=exportPortfolio;document.getElementById('exportCoordinatorSummary').onclick=exportCoordinatorSummary;document.getElementById('authBtn').onclick=()=>user?signOut():signIn();document.getElementById('accountAction').onclick=()=>user?signOut():signIn()}

bind();
renderHome();
initAuth();
